package zebra

// Solution holds the answers to the two zebra puzzle questions.
type Solution struct {
	DrinksWater string
	OwnsZebra   string
}

// Number of houses.
const houses = 5

// Items of each category. A permutation lists, for every house (index),
// which item of the category lives there.
const (
	englishman = iota
	spaniard
	ukrainian
	norwegian
	japanese
)

const (
	red = iota
	green
	ivory
	yellow
	blue
)

const (
	coffee = iota
	tea
	milk
	orangejuice
	water
)

const (
	dog = iota
	snails
	fox
	horse
	zebra
)

const (
	oldgold = iota
	kools
	chesterfields
	luckystrike
	parliaments
)

var nationalities = [...]string{
	"Englishman", "Spaniard", "Ukrainian", "Norwegian", "Japanese",
}

// houseOf returns the house (index) holding the given item of the
// permutation p, or -1 when the item is missing.
func houseOf(p []int, item int) int {
	for h, v := range p {
		if v == item {
			return h
		}
	}
	return -1
}

// nextTo reports whether houses a and b are neighbours.
func nextTo(a, b int) bool {
	d := a - b
	return d == 1 || d == -1
}

// permute iterates over all permutations of 0..houses-1, calling f for each
// complete permutation. If f returns true the iteration stops early.
func permute(cur []int, used []bool, k int, f func([]int) bool) bool {
	if k == houses {
		return f(cur)
	}
	for i := 0; i < houses; i++ {
		if used[i] {
			continue
		}
		used[i] = true
		cur[k] = i
		if permute(cur, used, k+1, f) {
			return true
		}
		used[i] = false
	}
	return false
}

func adjacent(p []int, item, other int) bool {
	a, b := houseOf(p, item), houseOf(p, other)
	return nextTo(a, b)
}

// SolvePuzzle searches the puzzle constraints and returns who drinks water
// and who owns the zebra.
func SolvePuzzle() Solution {
	var answer Solution

	color := make([]int, houses)
	nat := make([]int, houses)
	drink := make([]int, houses)
	smoke := make([]int, houses)

	// Colors first: rule 6 (green immediately right of ivory) and, together
	// with the nationalities, rule 15 (Norwegian next to the blue house).
	permute(color, make([]bool, houses), 0, func(c []int) bool {
		if houseOf(c, green) != houseOf(c, ivory)+1 {
			return false
		}

		// Nationalities: rule 2 (Englishman in red), 10 (Norwegian first),
		// 15 (blue house next to house 0, i.e. house 1).
		permute(nat, make([]bool, houses), 0, func(n []int) bool {
			if houseOf(n, englishman) != houseOf(c, red) {
				return false
			}
			if houseOf(n, norwegian) != 0 || houseOf(c, blue) != 1 {
				return false
			}

			// Drinks: rule 4 (coffee in green), 5 (Ukrainian drinks tea),
			// 9 (milk in the middle house).
			permute(drink, make([]bool, houses), 0, func(d []int) bool {
				if houseOf(d, coffee) != houseOf(c, green) {
					return false
				}
				if houseOf(d, tea) != houseOf(n, ukrainian) {
					return false
				}
				if houseOf(d, milk) != 2 {
					return false
				}

				// Smokes: rule 8 (Kools in yellow), 13 (Lucky Strike with
				// orange juice), 14 (Japanese smokes Parliaments).
				permute(smoke, make([]bool, houses), 0, func(s []int) bool {
					if houseOf(s, kools) != houseOf(c, yellow) {
						return false
					}
					if houseOf(s, luckystrike) != houseOf(d, orangejuice) {
						return false
					}
					if houseOf(s, parliaments) != houseOf(n, japanese) {
						return false
					}
					// rule 12 needs the pets, so it is checked there.

					// Pets: rule 3 (Spaniard owns the dog), 7 (Old Gold with
					// snails), 11 (Chesterfields next to fox), 12 (Kools next
					// to the horse).
					return permute(nat, make([]bool, houses), 0, func(p []int) bool {
						if houseOf(p, dog) != houseOf(n, spaniard) {
							return false
						}
						if houseOf(p, snails) != houseOf(s, oldgold) {
							return false
						}
						if !adjacent(p, fox, chesterfields) {
							return false
						}
						if !adjacent(p, horse, kools) {
							return false
						}

						answer = Solution{
							DrinksWater: nationalities[n[houseOf(d, water)]],
							OwnsZebra:   nationalities[n[houseOf(p, zebra)]],
						}
						return true
					})
				})
			})
			return false
		})
		return false
	})

	return answer
}

