func houseOf(p []int, item int) int {
	for h, v := range p {
		if v == item {
			return h
		}
	}
	return -1
}

// adjacent reports whether the two items are in neighbouring houses.
func adjacent(a []int, itemA int, b []int, itemB int) bool {
	d := houseOf(a, itemA) - houseOf(b, itemB)
	return d == 1 || d == -1
}

// permute walks over all permutations of 0..houses-1 and calls f for each
// complete one. If f returns true the iteration stops immediately.
func permute(cur []int, used []bool, k int, f func([]int) bool) bool {
	if k == houses {
		return f(cur)
	}
	for i := 0; i < houses; i++ {
		if used[i] {
			continue
		}
		used[i] = true
		cur[k] = i
		if permute(cur, used, k+1, f) {
			return true
		}
		used[i] = false
	}
	return false
}

